/**
 * Regenerate `lib/species/names.ts` — the species list behind the type-ahead.
 *
 *   node scripts/gen-species.mjs           # rewrite the list
 *   node scripts/gen-species.mjs --check   # fail if the committed list is stale
 *
 * WHY A GENERATED FILE INSTEAD OF READING @pkmn/dex AT RUNTIME: the dex is a
 * ~1.8MB minified chunk and this needs 1,317 rows out of it. Committing them
 * costs ~9KB gzipped, adds no runtime dependency, and keeps `lib/` pure — the
 * dex stays a build-time tool and a lazy import on the board, where its move
 * data actually earns its size.
 *
 * WHAT IS IN THE LIST: every species Showdown's icon sheet can draw. That is the
 * same test `isKnownSpecies` in app/demo/workflow-io.ts applies to a pasted
 * roster, so the picker and the paste importer agree by construction — the
 * picker can never offer a name the board would then reject.
 *
 * It is NOT a legality list. All generations, all regulations, Megas included;
 * xatu is not a legality checker (CLAUDE.md). Gigantamax and Totem formes are
 * dropped because they cannot appear in a doubles team preview, and the
 * Pokestar/CAP/LGPE fictions are dropped because they are not Pokémon.
 */

import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { Dex } from "@pkmn/dex";
import { Icons } from "@pkmn/img";

const OUT = join(
  dirname(fileURLToPath(import.meta.url)),
  "..",
  "lib",
  "species",
  "names.ts",
);

/** The icon sheet doubles as a dex: an unknown species falls back to tile 0. */
const hasIcon = (name) =>
  !/scroll 0px 0px/.test(Icons.getPokemon(name).css.background ?? "");

const UNDRAWABLE_IN_PREVIEW = /-(Gmax|Totem)$/;
const NOT_A_POKEMON = ["CAP", "Custom", "LGPE"];

const all = Dex.species.all();

/**
 * Same Pokémon, different paint — Unown letters, Vivillon patterns, Alcremie
 * creams, Furfrou trims, Minior colours. The dex says so itself, so no judgment
 * of ours is involved. Real formes like `Vivillon-Fancy` are `otherFormes` and
 * stay.
 */
const cosmetic = new Set(all.flatMap((s) => s.cosmeticFormes ?? []));

/**
 * Pikachu's fifteen costumes (Cosplay, Libre, the travel caps, Partner…) are
 * `otherFormes`, not `cosmeticFormes`, so nothing in the data separates them
 * from a Maushold-Four — hence this one hand-written exclusion. Typing "pika"
 * offered sixteen Pikachus and buried the only one anybody means (user,
 * 2026-08-13). None of them is a VGC roster entry; if one ever is, it can still
 * be pasted.
 */
const pikachuCostumes = new Set(Dex.species.get("Pikachu").otherFormes ?? []);

const kept = all
  .filter(
    (s) =>
      s.exists &&
      !UNDRAWABLE_IN_PREVIEW.test(s.name) &&
      !NOT_A_POKEMON.includes(s.isNonstandard ?? "") &&
      !cosmetic.has(s.name) &&
      !pikachuCostumes.has(s.name) &&
      hasIcon(s.name),
  )
  .sort((a, b) => a.name.localeCompare(b.name));

/**
 * `base|forme|types` — one line per species. Base and forme are stored apart so
 * a suggestion can be typeset the way Showdown does it (**Blastoise**-Mega), and
 * the types ride along because a row without them doesn't look like Showdown at
 * all. That is the whole reason for the ~2.4KB the types add.
 *
 * NFC, so "Flabébé" is one code point per accent and a caller comparing names
 * with === gets the answer it expects — the dex ships some names decomposed.
 */
const rows = kept.map((s) => {
  const base = s.baseSpecies.normalize("NFC");
  const forme = (s.forme ?? "").normalize("NFC");
  const rebuilt = forme ? `${base}-${forme}` : base;
  if (rebuilt !== s.name.normalize("NFC")) {
    throw new Error(`cannot rebuild ${s.name} from base+forme (${rebuilt})`);
  }
  if (/\|/.test(rebuilt)) throw new Error(`pipe in a species name: ${s.name}`);
  return `${base}|${forme}|${s.types.join("/")}`;
});

const body = `// GENERATED by scripts/gen-species.mjs — do not edit by hand.
// Every species Showdown's icon sheet can draw, so a picked name always has a
// sprite and always survives the board's paste import. Not a legality list.
// Each entry is \`base|forme|types\`; \`lib/species/search.ts\` parses it.
export const SPECIES_ROWS: readonly string[] = ${JSON.stringify(rows, null, 0).replace(/","/g, '",\n  "').replace(/^\["/, '[\n  "').replace(/"\]$/, '",\n]')};
`;

if (process.argv.includes("--check")) {
  const current = readFileSync(OUT, "utf8");
  if (current !== body) {
    console.error(`${OUT} is stale — run: node scripts/gen-species.mjs`);
    process.exit(1);
  }
  console.log(`up to date — ${rows.length} species`);
} else {
  writeFileSync(OUT, body);
  console.log(`wrote ${rows.length} species to ${OUT}`);
}
